import { createStore } from "vuex";
// Every course JSON in src/assets/<year>/<track>/ (generated by scripts/generate_courses.py)
const MONTHS = ["January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"];
const courseFiles = import.meta.glob("@/assets/*/*/*.json", { eager: true, import: "default" });
const courses = Object.values(courseFiles).sort((a, b) =>
    a.year - b.year
    || MONTHS.indexOf(a.term) - MONTHS.indexOf(b.term)
    || a.name.localeCompare(b.name)
);

const store = createStore({
    state() {
        return {
            courses: courses
        }
    },
    getters: {
        getCourses(state) {
            return state.courses;
        },
        filterCourses: (state) => (year, term) => {
            return state.courses.filter(x => x["year"] == year && x["term"] == term)
        }
    }
})

export default store;